+      let targetY = 0;
+      let currentX = 0;
+      let currentY = 0;
+      let frame;
+
+      const render = () => {
+        currentX += (targetX - currentX) * 0.075;
+        currentY += (targetY - currentY) * 0.075;
+        ramen.style.setProperty('--tilt-x', currentX.toFixed(3));
+        ramen.style.setProperty('--tilt-y', currentY.toFixed(3));
+        if (Math.abs(targetX - currentX) + Math.abs(targetY - currentY) > 0.002) {
+          frame = requestAnimationFrame(render);
+        } else {
+          frame = undefined;
+        }
+      };
