+      const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
+      let targetX = 0;
+      let targetY = 0;
+      let currentX = 0;
+      let currentY = 0;
+      let frame;
+
+      const render = () => {
+        currentX += (targetX - currentX) * 0.075;
+        currentY += (targetY - currentY) * 0.075;
+        ramen.style.setProperty('--tilt-x', currentX.toFixed(3));
+        ramen.style.setProperty('--tilt-y', currentY.toFixed(3));
+        if (Math.abs(targetX - currentX) + Math.abs(targetY - currentY) > 0.002) {
+          frame = requestAnimationFrame(render);
+        } else {
+          frame = undefined;
+        }
+      };
+
+      const move = (event) => {
+        if (reducedMotion.matches) return;
+        const x = event.clientX / window.innerWidth;
+        const y = event.clientY / window.innerHeight;
+        targetX = (x - 0.5) * 2;
+        targetY = (y - 0.5) * 2;
+        stage.style.setProperty('--mouse-x', `${(x * 100).toFixed(2)}%`);
+        stage.style.setProperty('--mouse-y', `${(y * 100).toFixed(2)}%`);
+        if (!frame) frame = requestAnimationFrame(render);
+      };
+
+      const reset = () => {
+        targetX = 0;
+        targetY = 0;
+        stage.style.setProperty('--mouse-x', '50%');
+        stage.style.setProperty('--mouse-y', '45%');
+        if (!reducedMotion.matches && !frame) frame = requestAnimationFrame(render);
+      };
+
+      window.addEventListener('pointermove', move, { passive: true });
+      window.addEventListener('pointerleave', reset, { passive: true });
+      document.addEventListener('visibilitychange', () => {
+        if (document.hidden && frame) {
+          cancelAnimationFrame(frame);
+          frame = undefined;
+        }
+      });
+      reducedMotion.addEventListener('change', (event) => {
+        if (event.matches) {
+          targetX = currentX = targetY = currentY = 0;
+          ramen.style.setProperty('--tilt-x', 0);
+          ramen.style.setProperty('--tilt-y', 0);
+          if (frame) cancelAnimationFrame(frame);
+          frame = undefined;
+        }
+      });
+    })();
+  </script>
